<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,message,notify,genres,type Work} from '../api'
import {adminDate,workStatusLabels,isPersonalAdmin} from '../composables/admin'
import Icon from '../components/Icon.vue'
import AdminDialog from '../components/AdminDialog.vue'
import ArticleBody from '../components/ArticleBody.vue'
import '../article/article.css'
interface ReviewItem {id:number;workId:number;findings:string;createdAt:string;authorName:string;title:string}
interface ReviewDetail extends ReviewItem {submission:{title:string;body:string;genre:string;layout?:Work['layout'];notes:string;excerpt:string;byline:string}}
const reviews=ref<ReviewItem[]>([]),reviewDetail=ref<ReviewDetail|null>(null),reviewNote=ref(''),reviewError=ref(''),reviewBusy=ref(false)
async function loadReviews(){try{reviews.value=(await api.get('/admin/article-reviews')).data}catch(e){reviewError.value=message(e)}}
async function openReview(id:number){reviewError.value='';try{reviewDetail.value=(await api.get(`/admin/article-reviews/${id}`)).data;reviewNote.value=''}catch(e){reviewError.value=message(e)}}
async function decideReview(approve:boolean){if(!reviewDetail.value||reviewBusy.value)return;if(!approve&&!reviewNote.value.trim()){reviewError.value='请填写退回原因';return}if(approve&&!confirm('确认通过并公开此提交版本？'))return;reviewBusy.value=true;reviewError.value='';try{await api.post(`/admin/article-reviews/${reviewDetail.value.id}/decision`,{approve,note:reviewNote.value});reviewDetail.value=null;await Promise.all([loadReviews(),load()]);notify(approve?'复核通过，已公开提交版本':'已退回复核申请')}catch(e){reviewError.value=message(e)}finally{reviewBusy.value=false}}
void loadReviews()
const route=useRoute(),router=useRouter()
const works=ref<Work[]>([]),total=ref(0),page=ref(1),loading=ref(true),error=ref(''),busy=ref<number[]>([])
const summary=ref({total:0,published:0,draft:0,withdrawn:0,featured:0})
const q=ref(String(route.query.q||'')),genre=ref(String(route.query.genre||'')),sort=ref(String(route.query.sort||'updated'))
const status=computed(()=>['PUBLISHED','WITHDRAWN'].includes(String(route.query.status))?String(route.query.status):''),featured=computed(()=>route.query.featured==='true')
const preview=ref<Work|null>(null),previewLoading=ref(false),previewError=ref(''),withdrawTarget=ref<Work|null>(null),withdrawError=ref('')
const deleteTarget=ref<Work|null>(null),deleteError=ref(''),approveTarget=ref<Work|null>(null),approveError=ref('')
const pages=computed(()=>Math.max(1,Math.ceil(total.value/12)))
let request=0,previewRequest=0,disposed=false
onBeforeUnmount(()=>{disposed=true;request++;previewRequest++})
function isFeatured(work:Work){return work.tags.some(t=>t.name==='海燕精选')}
async function load(){const version=++request;loading.value=true;error.value='';try{const {data}=await api.get('/admin/works',{params:{q:route.query.q||'',genre:route.query.genre||'',sort:route.query.sort||'updated',status:status.value,featured:featured.value,page:Math.max(1,Number(route.query.page)||1),pageSize:12}});if(disposed||version!==request)return;works.value=data.items;total.value=data.total;page.value=data.page;summary.value=data.summary}catch(e){if(version===request)error.value=message(e)}finally{if(version===request)loading.value=false}}
function filter(values:Record<string,string|undefined>){void router.push({query:{...route.query,...values,page:undefined}})}
function search(){filter({q:q.value.trim()||undefined,genre:genre.value||undefined,sort:sort.value==='updated'?undefined:sort.value})}
function reset(){q.value='';genre.value='';sort.value='updated';void router.push({query:{}})}
async function openPreview(id:number){const version=++previewRequest;preview.value=null;previewLoading.value=true;previewError.value='';try{const {data}=await api.get(`/admin/works/${id}`);if(version===previewRequest&&!disposed)preview.value=data}catch(e){if(version===previewRequest)previewError.value=message(e)}finally{if(version===previewRequest)previewLoading.value=false}}
function closePreview(){previewRequest++;preview.value=null;previewLoading.value=false;previewError.value='';if(route.query.work)void router.replace({query:{...route.query,work:undefined}})}
async function toggleFeatured(work:Work){if(busy.value.includes(work.id))return;busy.value.push(work.id);const active=!isFeatured(work);try{await api.put(`/admin/works/${work.id}/featured`,{active});await load();if(preview.value?.id===work.id)await openPreview(work.id);notify(active?'已加入海燕精选':'已取消海燕精选')}catch(e){notify(message(e))}finally{busy.value=busy.value.filter(id=>id!==work.id)}}
function askWithdraw(work:Work){withdrawTarget.value=work;withdrawError.value=''}
async function withdraw(){const work=withdrawTarget.value;if(!work||busy.value.includes(work.id))return;busy.value.push(work.id);withdrawError.value='';try{await api.post(`/admin/works/${work.id}/withdraw`);withdrawTarget.value=null;if(preview.value?.id===work.id)closePreview();await load();notify('文章已下架，访客将无法继续访问')}catch(e){withdrawError.value=message(e)}finally{busy.value=busy.value.filter(id=>id!==work.id)}}
async function removeArticle(){const work=deleteTarget.value;if(!work||busy.value.includes(work.id))return;busy.value.push(work.id);deleteError.value='';try{await api.delete(`/admin/works/${work.id}`);deleteTarget.value=null;if(preview.value?.id===work.id)closePreview();await load();notify('文章已永久删除')}catch(e){deleteError.value=message(e)}finally{busy.value=busy.value.filter(id=>id!==work.id)}}
async function approve(){const work=approveTarget.value;if(!work||busy.value.includes(work.id))return;busy.value.push(work.id);approveError.value='';try{await api.post(`/admin/works/${work.id}/approve`);approveTarget.value=null;await load();if(preview.value?.id===work.id)await openPreview(work.id);notify('审核通过，文章已恢复公开')}catch(e){approveError.value=message(e)}finally{busy.value=busy.value.filter(id=>id!==work.id)}}
watch(()=>[route.query.q,route.query.genre,route.query.sort,route.query.status,route.query.featured,route.query.page],()=>{q.value=String(route.query.q||'');genre.value=String(route.query.genre||'');sort.value=String(route.query.sort||'updated');void load()},{immediate:true})
watch(()=>route.query.work,id=>{if(id&&/^\d+$/.test(String(id)))void openPreview(Number(id))},{immediate:true})
</script>
<template>
  <header class="admin-page-heading"><div><p class="admin-kicker">CONTENT MANAGEMENT</p><h1>文章管理 <span>/ 审核</span></h1><p>让每一封来信被妥善整理，让好的文字被更多人看见。</p></div><button class="button secondary small" :disabled="loading" @click="load"><Icon name="RefreshCw" :size="15"/>刷新文章</button></header>
  <section class="admin-section"><div class="admin-section-title"><div><h2>人工复核申请</h2><p>作者主动提交的版本，修改后申请会失效。</p></div><button class="admin-inline-link" @click="loadReviews">刷新申请</button></div><p v-if="reviewError&&!reviewDetail" class="error-message" role="alert">{{reviewError}}</p><div class="admin-surface"><p v-if="!reviews.length" class="admin-empty">暂无待复核申请</p><div v-for="item in reviews" :key="item.id" class="admin-recent"><div><strong>{{item.title||'未命名稿件'}}</strong><small>{{item.authorName}} · {{item.findings}} · {{adminDate(item.createdAt)}}</small></div><button class="button secondary small" @click="openReview(item.id)">查看并复核</button></div></div></section>
  <AdminDialog v-if="reviewDetail" title="人工复核申请" wide :busy="reviewBusy" @close="reviewDetail=null"><p v-if="reviewError" class="error-message" role="alert">{{reviewError}}</p><div class="admin-preview-heading"><h2>{{reviewDetail.submission.title}}</h2><p>提交账号：{{reviewDetail.authorName}} · {{reviewDetail.findings}}</p><p>署名：{{reviewDetail.submission.byline}} · 摘要：{{reviewDetail.submission.excerpt}}</p></div><ArticleBody :html="reviewDetail.submission.body" :genre="reviewDetail.submission.genre" :layout="reviewDetail.submission.layout" compact/><p v-if="reviewDetail.submission.notes" class="admin-preview-note">附记：{{reviewDetail.submission.notes}}</p><label>复核意见（退回时必填）<textarea v-model="reviewNote" maxlength="500" rows="3"/></label><footer class="admin-form-actions"><button class="button secondary" :disabled="reviewBusy" @click="decideReview(false)">退回修改</button><button class="button" :disabled="reviewBusy" @click="decideReview(true)">审核通过并发布</button></footer></AdminDialog>
  <div class="admin-info"><Icon name="ShieldCheck" :size="20"/><p><strong>自动审核 + 人工巡查</strong>文章经自动检查后公开；需要复核或自动检查暂不可用时，作者可申请人工复核。可恢复已下架文章、管理精选或下架内容。</p></div>
  <div class="admin-subnav admin-status-tabs" aria-label="文章状态"><button :class="{selected:!status&&!featured}" @click="filter({status:undefined,featured:undefined})">全部文章<span>{{summary.total}}</span></button><button v-for="s in [{key:'PUBLISHED',label:'已公开',count:summary.published},{key:'WITHDRAWN',label:'下架',count:summary.withdrawn}]" :key="s.key" :class="{selected:status===s.key&&!featured}" @click="filter({status:s.key,featured:undefined})">{{s.label}}<span>{{s.count}}</span></button><button :class="{selected:featured}" @click="filter({status:undefined,featured:'true'})"><Icon name="Sparkles" :size="14"/>海燕精选<span>{{summary.featured}}</span></button></div>
  <form class="admin-filters" @submit.prevent="search"><label class="admin-search-field"><Icon name="Search" :size="17"/><input v-model="q" maxlength="100" aria-label="搜索文章" placeholder="搜索文章标题、署名或发布账号"/></label><label><span class="sr-only">文章体裁</span><select v-model="genre" aria-label="文章体裁" @change="search"><option value="">全部体裁</option><option v-for="g in genres.slice(1)" :key="g">{{g}}</option></select></label><label><span class="sr-only">文章排序</span><select v-model="sort" aria-label="文章排序" @change="search"><option value="updated">最近更新</option><option value="newest">最新创建</option><option value="oldest">最早创建</option></select></label><button class="button small">搜索</button></form>
  <p v-if="error" class="error-message" role="alert">{{error}} <button @click="load">重新加载</button></p>
  <div class="admin-table-wrap"><table class="admin-table admin-works-table"><thead><tr><th>文章</th><th>署名 / 发布账号</th><th>状态</th><th>更新时间</th><th class="admin-cell-end">管理操作</th></tr></thead><tbody v-if="!loading&&!error"><tr v-for="w in works" :key="w.id"><td><button class="admin-work-title" @click="openPreview(w.id)">{{w.title||'未命名稿件'}}</button><div class="admin-work-meta"><span>{{w.customGenre||w.genre}}</span><span>{{w.wordCount}} 字</span><span v-if="isFeatured(w)" class="admin-featured-label"><Icon name="Sparkles" :size="12"/>精选</span></div></td><td><strong class="admin-byline">{{w.displayByline||w.authorName}}</strong><small class="admin-account-byline">{{w.authorName}}</small></td><td><span class="admin-badge" :class="w.status.toLowerCase()">{{workStatusLabels[w.status]||w.status}}</span></td><td class="admin-muted">{{adminDate(w.updatedAt)}}</td><td><div class="admin-row-actions"><button @click="openPreview(w.id)">预览</button><button v-if="w.status==='PUBLISHED'||isFeatured(w)" :class="{'admin-featured-label':isFeatured(w)}" :disabled="busy.includes(w.id)" @click="toggleFeatured(w)">{{isFeatured(w)?'取消精选':'加入精选'}}</button><button v-if="w.status==='PUBLISHED'" class="admin-danger-link" :disabled="busy.includes(w.id)" @click="askWithdraw(w)">下架</button><button v-if="w.status==='WITHDRAWN'" :disabled="busy.includes(w.id)" @click="approveTarget=w;approveError=''">审核通过</button><button v-if="isPersonalAdmin()" class="admin-danger-link" :disabled="busy.includes(w.id)" @click="deleteTarget=w;deleteError=''">删除文章</button></div></td></tr></tbody></table><div v-if="loading" class="admin-empty" role="status">正在加载文章…</div><div v-else-if="!error&&!works.length" class="admin-empty"><Icon name="FileText" :size="30"/><h3>没有找到相关文章</h3><p>试试其他关键词，或查看全部文章。</p><button class="admin-inline-link" @click="reset">重置筛选</button></div></div>
  <div class="admin-table-footer"><p>共 {{total}} 篇文章 · 每页 12 篇</p><div class="admin-pagination"><button :disabled="loading||page<=1" aria-label="上一页文章" @click="router.push({query:{...route.query,page:String(page-1)}})"><Icon name="ChevronLeft" :size="16"/></button><span>{{page}} / {{pages}}</span><button :disabled="loading||page>=pages" aria-label="下一页文章" @click="router.push({query:{...route.query,page:String(page+1)}})"><Icon name="ChevronRight" :size="16"/></button></div></div>
  <AdminDialog v-if="preview||previewLoading||previewError" title="文章预览 / 内容巡查" wide @close="closePreview"><p v-if="previewLoading" class="admin-empty">正在读取正文…</p><p v-if="previewError" class="error-message" role="alert">{{previewError}}</p><template v-if="preview"><div class="admin-preview-heading"><span class="admin-badge" :class="preview.status.toLowerCase()">{{workStatusLabels[preview.status]||preview.status}}</span><h2>{{preview.title||'未命名稿件'}}</h2><p>{{preview.displayByline||preview.authorName}} · 发布账号：{{preview.authorName}} · {{preview.wordCount}} 字</p><p>更新于 {{adminDate(preview.updatedAt)}}</p></div><ArticleBody :html="preview.body" :genre="preview.genre" :layout="preview.layout" compact/><p v-if="preview.sourceNote" class="admin-preview-note">来源：{{preview.sourceNote}}</p><p v-if="preview.notes" class="admin-preview-note">附记：{{preview.notes}}</p><footer class="admin-form-actions"><RouterLink v-if="preview.status==='PUBLISHED'" :to="`/work/${preview.id}`" class="admin-inline-link">打开公开页面 <Icon name="ArrowUpRight" :size="14"/></RouterLink><button v-if="preview.status==='PUBLISHED'||isFeatured(preview)" class="button secondary" :disabled="busy.includes(preview.id)" @click="toggleFeatured(preview)">{{isFeatured(preview)?'取消精选':'加入精选'}}</button><button v-if="preview.status==='PUBLISHED'" class="button admin-danger-button" :disabled="busy.includes(preview.id)" @click="askWithdraw(preview)">下架文章</button><button v-if="preview.status==='WITHDRAWN'" class="button" :disabled="busy.includes(preview.id)" @click="approveTarget=preview;approveError=''">审核通过</button><button v-if="isPersonalAdmin()" class="button admin-danger-button" :disabled="busy.includes(preview.id)" @click="deleteTarget=preview;deleteError=''">删除文章</button></footer></template></AdminDialog>
  <AdminDialog v-if="withdrawTarget" title="确认下架文章" :busy="busy.includes(withdrawTarget.id)" @close="withdrawTarget=null"><p v-if="withdrawError" class="error-message" role="alert">{{withdrawError}}</p><div class="admin-confirm-copy"><h3>《{{withdrawTarget.title}}》</h3><p>下架后，文章将从公开书架和首页推荐中移除，访客无法访问。稿件内容保留，作者可在书桌中修改后重新发布。</p></div><footer class="admin-form-actions"><button class="button secondary" :disabled="busy.includes(withdrawTarget.id)" @click="withdrawTarget=null">取消</button><button class="button admin-danger-button" :disabled="busy.includes(withdrawTarget.id)" @click="withdraw">{{busy.includes(withdrawTarget.id)?'下架中…':'确认下架'}}</button></footer></AdminDialog>
  <AdminDialog v-if="deleteTarget" title="永久删除文章" :busy="busy.includes(deleteTarget.id)" @close="deleteTarget=null"><div class="admin-confirm-copy"><h3>《{{deleteTarget.title}}》</h3><p>将永久删除文章正文、私有修订稿、历史版本、评论与收藏记录。此操作无法恢复。</p></div><p v-if="deleteError" class="error-message" role="alert">{{deleteError}}</p><footer class="admin-form-actions"><button class="button secondary" :disabled="busy.includes(deleteTarget.id)" @click="deleteTarget=null">取消</button><button class="button admin-danger-button" :disabled="busy.includes(deleteTarget.id)" @click="removeArticle">确认永久删除文章</button></footer></AdminDialog>
  <AdminDialog v-if="approveTarget" title="审核通过并恢复公开" :busy="busy.includes(approveTarget.id)" @close="approveTarget=null"><div class="admin-confirm-copy"><h3>《{{approveTarget.title}}》</h3><p>审核通过后恢复文章上次提交的公开版本。未绑定账号的文章将归当前公用账号，并保留原署名；请先切换到公用身份。</p></div><p v-if="approveError" class="error-message" role="alert">{{approveError}}</p><footer class="admin-form-actions"><button class="button secondary" :disabled="busy.includes(approveTarget.id)" @click="approveTarget=null">取消</button><button class="button" :disabled="busy.includes(approveTarget.id)" @click="approve">确认审核通过</button></footer></AdminDialog>
</template>
